--
-- Table structure for table `product`
--

DROP TABLE IF EXISTS `product`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `product` (
  `ID` int NOT NULL AUTO_INCREMENT,
  `ProductType` int NOT NULL,
  `Title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `ShortDesc` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `LongDesc` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `Slug` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `HSN` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `GST` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `ShippingCharges` decimal(18,2) NOT NULL DEFAULT '0.00',
  `CategoryID` int NOT NULL,
  `SubcategoryID` int NOT NULL,
  `CreatedDtTm` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `ModifiedDtTm` datetime DEFAULT NULL,
  `IsActive` int NOT NULL DEFAULT '1',
  `DealOnOff` int NOT NULL DEFAULT '0',
  `Trending` int NOT NULL DEFAULT '0',
  `MostBuyed` int NOT NULL DEFAULT '0',
