INSERT INTO `product` VALUES (22,3,'Smartivity DIY Solar System Kit','<p><span class=\"ql-size-small\" style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\">Gear-Driven Working Model of Planets | Birthday Gift for Boys &amp; Girls 8-14 YearsI Build, Rotate &amp; Explore Astronomy | Learn Solar System &amp; Science Facts</span></p><p><span class=\"ql-size-small\"><span class=\"ql-cursor\">﻿﻿</span></span></p>','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\">HANDS-ON SOLAR SYSTEM EXPLORATION: Build a gear-driven working model of the solar system where planets rotate and orbit just like in space. Kids assemble the structure step by step and bring astronomy to life through hands-on construction, learning how planets move around the sun in an engaging and visual way. Designed for boys and girls aged 8 to 14 years.</span></p><p><br></p>','smartivity-diy-solar-system-kit','Ed123','18',40.00,22,28,'2026-02-25 07:20:55','2026-02-25 12:52:35',1,0,0,1,1),(23,4,'test','<p>testt</p>','<p>test</p>','test','s2342','18',40.00,22,27,'2026-02-25 07:35:53','2026-02-25 13:05:53',1,0,0,1,1),(24,3,'ABC Puzzle Montessori Educational and Learning Toy','<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(33, 33, 33); background-color: initial;\">Complete Set: Dive into the alphabet adventure with a wooden board and 26 funky capital letter buddies.</span></li></ol><p><br></p>','<p><strong style=\"color: rgb(33, 33, 33); background-color: initial;\">Skills Development</strong></p><ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(33, 33, 33); background-color: initial;\">Letter Learning Fun: Help your little one master the ABCs by fitting each colorful letter into its special spot. It\'s like a puzzle party for the brain.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(33, 33, 33); background-color: initial;\">Fine Motor Skills: Grab, twist, and place. This puzzle is a hands-on workout for tiny fingers, helping to build dexterity and coordination.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(33, 33, 33); background-color: initial;\">Vocabulary Voyage: Explore the world of words. With pictures under each piece, your child will expand their vocabulary while playing.</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(33, 33, 33); background-color: initial;\">Colorful Creativity: Dive into a rainbow of hues. Sorting and matching the vibrant letters boosts color recognition skills in a fun-filled way.</span></li></ol><p><br></p>','abc-puzzle-montessori-educational-and-learning-toy','Ed111','18',40.00,22,28,'2026-02-26 00:43:59','2026-02-26 06:13:59',1,0,0,1,1),(25,3,'Marvel Spiderman Action Figure (9.5 Inches, Multicolor)','<p><span style=\"background-color: rgb(255, 255, 255); color: rgb(15, 17, 17);\">Toys for Kids Ages 4 and Up</span></p><p><br></p>','<ol><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(15, 17, 17); background-color: rgb(255, 255, 255);\">Features multiple points of articulation</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(15, 17, 17); background-color: rgb(255, 255, 255);\">With Marvel, anyone can imagine suiting up like their favorite heroes and defending the world from evil</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(15, 17, 17); background-color: rgb(255, 255, 255);\">Collect all Marvel action figures and join Marvel heroes as they save the world from villains</span></li><li data-list=\"bullet\"><span class=\"ql-ui\" contenteditable=\"false\"></span><span style=\"color: rgb(1